parameters.jsCode:
// Assemble final Markdown document from all sections and diagrams
const input = $input.first().json;

const analysis = input.analysis || {};
const research = input.research || {};
const template = input.template || {};
const sections = input.sections || {};
const diagrams = input.diagrams || {};

const title = analysis.intent_summary || 'Untitled Document';
const docType = template.template_type || 'requirements';

// Build YAML frontmatter
const frontmatter = `---\ntitle: "${title}"\ntype: ${docType}\ngenerated_at: ${new Date().toISOString()}\nstatus: draft\n---\n\n`;

// Build table of contents
const toc = `# ${title}\n\n## Table of Contents\n\n${Object.keys(sections).map((s, i) => `${i + 1}. [${s}](#${s.toLowerCase().replace(/\s+/g, '-')})`).join('\n')}\n\n`;

// Build sections
let body = '';
for (const [sectionName, sectionData] of Object.entries(sections)) {
  const content = typeof sectionData === 'string' ? sectionData : (sectionData.content || '');
  body += `## ${sectionName}\n\n${content}\n\n---\n\n`;
}

// Build diagrams section
let diagramsSection = '## Diagrams\n\n';
const diagramTypes = ['architecture_diagram', 'data_flow_diagram', 'er_diagram', 'sequence_diagram'];
const diagramLabels = ['Architecture Diagram', 'Data Flow Diagram', 'ER Diagram', 'Sequence Diagram'];

for (let i = 0; i < diagramTypes.length; i++) {
  const diag = diagrams[diagramTypes[i]] || '';
  if (diag && diag.trim().length > 0) {
    diagramsSection += `### ${diagramLabels[i]}\n\n\`\`\`mermaid\n${diag}\n\`\`\`\n\n`;
  }
}

// Combine everything
const markdown = frontmatter + toc + body + diagramsSection;

// Generate document ID
const documentId = 'draft_' + Date.now();

return [{
  json: {
    documentId: documentId,
    title: title,
    content: markdown,
    markdown: markdown,
    sections: Object.keys(sections),
    diagrams: Object.keys(diagrams).filter(k => diagrams[k] && diagrams[k].trim().length > 0),
    templateName: template.selected_template || 'Default',
    sessionId: input.sessionId,
    status: 'pending_review'
  }
}];

